package com.snaphere.api.auth;
import com.snaphere.api.common.error.*; import com.snaphere.api.common.web.*; import jakarta.servlet.http.HttpServletRequest; import org.springframework.boot.context.properties.EnableConfigurationProperties; import org.springframework.context.annotation.*; import org.springframework.http.MediaType; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import java.io.IOException;
@Configuration @EnableWebSecurity @EnableConfigurationProperties(AuthProperties.class) class SecurityConfig {
 @Bean SecurityFilterChain securityFilterChain(HttpSecurity http,JwtAuthenticationFilter jwt)throws Exception{return http.csrf(c->c.disable()).cors(org.springframework.security.config.Customizer.withDefaults()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/v1/auth/google","/api/v1/auth/refresh","/api/v1/auth/restore").permitAll().requestMatchers("/api/v1/admin/**").hasRole("ADMIN").requestMatchers(org.springframework.http.HttpMethod.GET,"/api/v1/**").permitAll().requestMatchers("/api/v1/**").authenticated().anyRequest().permitAll()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).exceptionHandling(e->e.authenticationEntryPoint(this::unauthorized)).build();}
 private void unauthorized(HttpServletRequest r,jakarta.servlet.http.HttpServletResponse s,org.springframework.security.core.AuthenticationException e)throws IOException{s.setStatus(401);s.setContentType(MediaType.APPLICATION_JSON_VALUE);new com.fasterxml.jackson.databind.ObjectMapper().writeValue(s.getOutputStream(),ApiResponse.fail(ErrorBody.of(ErrorCode.AUTH_REQUIRED),TraceIdFilter.currentTraceId(r)));}
}
